bowedViolaGrittyWide.source:
dsp GenBowedViolaGrittyWide where
  param freq : Hz @control := 220.0 range 24.0 12000.0
  param gate : Unit @control := 0.0 range 0.0 1.0
  param colour : Unit @control := 0.5 range 0.0 1.0
  param life : Seconds @control := 0.6 range 0.03 8.0
  state previous : F32 := 0.0
  state env : F32 := 0.0
  state ph : F32 := 0.0
  state vib : F32 := 0.0
  state ve : F32 := 0.0
  state i1l : F32 := 0.0
  state i2l : F32 := 0.0
  state i1a : F32 := 0.0
  state i2a : F32 := 0.0
  state i1b : F32 := 0.0
  state i2b : F32 := 0.0
  state counter : F32 := 1.0
  sample x =>
    let trigger := gt(gate, previous + 0.001)
    let nz := noise1(noise1(counter) * 437.5453 + counter * 0.6180339)
    set counter := select(gt(counter, 1000000.0), 1.0, counter + 1.0)
    let envC := select(gt(gate, env), 1.0 - expneg(1.0 / (0.1 * sr)), 1.0 - expneg(5.0 / (life * sr)))
    let envA := env + envC * (gate - env)
    set env := envA
    set vib := fract(vib + 6.2 / sr)
    let veA := ve + (envA - ve) * (1.0 - expneg(1.0 / (0.35 * sr)))
    set ve := veA
    let f := max(24.0, freq) * (1.0 + sinpi(vib * 2.0) * 0.009 * veA)
    let phA := fract(ph + f / sr)
    set ph := phA
    let saw := phA * 2.0 - 1.0
    let bowNoise := nz * envA * 0.09 * (1.0 + 2.0 * max(0.0, 0.6 - envA))
    let drive := saw * envA + bowNoise
    let gl := tanpi(min(0.45, max(10.0, f * 7.5 * (0.6 + colour)) / sr))
    let kl := 1.0
    let al := 1.0 / (1.0 + gl * (gl + kl))
    let v1l := al * (i1l + gl * (drive - i2l))
    let v2l := i2l + gl * v1l
    set i1l := 2.0 * v1l - i1l
    set i2l := 2.0 * v2l - i2l
    let ga := tanpi(min(0.45, max(10.0, 350.0) / sr))
    let ka := 0.9
    let aa := 1.0 / (1.0 + ga * (ga + ka))
    let v1a := aa * (i1a + ga * (v2l - i2a))
    let v2a := i2a + ga * v1a
    set i1a := 2.0 * v1a - i1a
    set i2a := 2.0 * v2a - i2a
    let gb := tanpi(min(0.45, max(10.0, 2200.0) / sr))
    let kb := 1.4
    let ab := 1.0 / (1.0 + gb * (gb + kb))
    let v1b := ab * (i1b + gb * (v2l - i2b))
    let v2b := i2b + gb * v1b
    set i1b := 2.0 * v1b - i1b
    set i2b := 2.0 * v2b - i2b
    set previous := gate
    return softsign((v2l * 0.6 + v1a * 0.5 + v1b * 0.35) * 1.6) * 0.4645

